BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SELECT extensions.no_plan();
INSERT INTO auth.users(id,aud,role,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
SELECT ('b1100000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'authenticated','authenticated','legacy-award-'||n||'@local.test',now(),'{}',jsonb_build_object('username','legacy_award_'||n),now(),now() FROM generate_series(1,4) n;
INSERT INTO public.projects(id,creator_id,title,location,description,event_type,verification_method,schedule,status,project_timezone) VALUES
 ('b1200000-0000-4000-8000-000000000001','b1100000-0000-4000-8000-000000000001','Legacy awards fixture','Local','Synthetic historical awards','oneTime','manual','{"oneTime":{"date":"2020-09-18","startTime":"09:00","endTime":"15:00","volunteers":5}}','upcoming','UTC');
INSERT INTO public.project_signups(id,project_id,user_id,schedule_id,status)
SELECT ('b1300000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'b1200000-0000-4000-8000-000000000001',('b1100000-0000-4000-8000-'||lpad((n+1)::text,12,'0'))::uuid,'oneTime','approved' FROM generate_series(1,3) n;
INSERT INTO public.certificates(id,project_id,signup_id,volunteer_name,volunteer_email,project_title,event_start,event_end,is_certified,creator_id,type,check_in_method,schedule_id)
SELECT ('b1400000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'b1200000-0000-4000-8000-000000000001',('b1300000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'Historical volunteer','legacy-award-'||(n+1)||'@local.test','Historical project title','2020-09-18T09:00:00Z','2020-09-18T13:00:00Z',false,'b1100000-0000-4000-8000-000000000001',NULL,'manual','oneTime' FROM generate_series(1,2) n;
CREATE TEMP TABLE original_legacy AS SELECT id,to_jsonb(certificates) AS snapshot FROM public.certificates WHERE project_id='b1200000-0000-4000-8000-000000000001';
SELECT extensions.throws_ok($$INSERT INTO public.certificates(project_id,signup_id,project_title,event_start,event_end,is_certified,type,check_in_method) VALUES('b1200000-0000-4000-8000-000000000001','b1300000-0000-4000-8000-000000000001','Duplicate','2020-09-18T09:00:00Z','2020-09-18T13:00:00Z',false,'verified','manual')$$,'23505','platform award already exists; use the correction workflow','verified insertion cannot duplicate a NULL-type platform award');
SELECT extensions.throws_ok($$SELECT public.publish_volunteer_hours_transactional('b1100000-0000-4000-8000-000000000001','b1200000-0000-4000-8000-000000000001','oneTime','[{"signupId":"b1300000-0000-4000-8000-000000000002","checkIn":"2020-09-18T09:00:00Z","checkOut":"2020-09-18T13:00:00Z","attendanceRevision":0}]','hours-publication:v1:'||repeat('b1',32))$$,'23505','platform award already exists; use the correction workflow','publication recognizes the existing legacy award');
UPDATE public.projects SET published='{"oneTime":true}' WHERE id='b1200000-0000-4000-8000-000000000001';
UPDATE public.project_signups SET status='attended',check_in_time='2020-09-18T09:00:00Z',check_out_time='2020-09-18T13:00:00Z' WHERE id='b1300000-0000-4000-8000-000000000002';
SELECT extensions.is((SELECT count(*)::integer FROM public.certificates WHERE signup_id='b1300000-0000-4000-8000-000000000002'),1,'late attendance cannot duplicate the legacy award');
SELECT extensions.is((SELECT count(*)::integer FROM public.issue_supplemental_verified_certificates('b1200000-0000-4000-8000-000000000001','oneTime',ARRAY['b1300000-0000-4000-8000-000000000002']::uuid[],'b1100000-0000-4000-8000-000000000001')),0,'direct supplemental issuance skips a legacy award');
SELECT extensions.is((SELECT to_jsonb(certificates) FROM public.certificates WHERE id='b1400000-0000-4000-8000-000000000002'),(SELECT snapshot FROM original_legacy WHERE id='b1400000-0000-4000-8000-000000000002'),'late and supplemental paths preserve the entire historical snapshot');
SELECT extensions.is(public.record_project_attendance('b1300000-0000-4000-8000-000000000001',0,'Reviewed historical attendance','[{"checkIn":"2020-09-18T09:00:00Z","checkOut":"2020-09-18T13:00:00Z"}]','b1500000-0000-4000-8000-000000000001','b1100000-0000-4000-8000-000000000001')->>'certificateId','b1400000-0000-4000-8000-000000000001','recording returns the existing legacy certificate');
SELECT extensions.is(public.correct_project_attendance('b1300000-0000-4000-8000-000000000001',1,'Reviewed break on original sheet','[{"checkIn":"2020-09-18T09:00:00Z","checkOut":"2020-09-18T10:00:00Z"},{"checkIn":"2020-09-18T12:00:00Z","checkOut":"2020-09-18T13:00:00Z"}]','b1500000-0000-4000-8000-000000000002','b1100000-0000-4000-8000-000000000001')->>'creditedMinutes','120','explicit correction updates canonical minutes on the legacy certificate');
SELECT extensions.ok((SELECT type IS NULL AND credited_minutes=120 AND attendance_revision=2 AND project_title='Historical project title' FROM public.certificates WHERE id='b1400000-0000-4000-8000-000000000001'),'correction preserves legacy type, URL identity, and historical project title');
SELECT extensions.is((SELECT old_credited_minutes FROM private.project_attendance_changes WHERE request_id='b1500000-0000-4000-8000-000000000002'),240,'correction records the previous legacy award');
SELECT extensions.is((SELECT count(*)::integer FROM public.certificates WHERE signup_id='b1300000-0000-4000-8000-000000000001'),1,'recording and correction keep exactly one award');
SELECT extensions.is((SELECT count(*)::integer FROM public.hours_publication_email_outbox outbox JOIN public.certificates cert ON cert.id=outbox.certificate_id WHERE cert.project_id='b1200000-0000-4000-8000-000000000001'),0,'legacy record and correction do not automatically resend');
INSERT INTO public.project_paper_scan_batches(id,project_id,schedule_id,created_by,status,image_count) VALUES('b1600000-0000-4000-8000-000000000001','b1200000-0000-4000-8000-000000000001','oneTime','b1100000-0000-4000-8000-000000000001','review',1);
INSERT INTO public.project_paper_scan_rows(id,batch_id,project_id,sheet_row_number,raw_extraction,name,decision,match_signup_id,attendance_intervals,review_acknowledged,identity_confirmed) VALUES('b1700000-0000-4000-8000-000000000001','b1600000-0000-4000-8000-000000000001','b1200000-0000-4000-8000-000000000001',1,'{}','Historical volunteer','include','b1300000-0000-4000-8000-000000000001','[{"checkIn":"2020-09-18T09:00:00Z","checkOut":"2020-09-18T09:30:00Z"},{"checkIn":"2020-09-18T11:30:00Z","checkOut":"2020-09-18T13:00:00Z"}]',true,true);
SELECT extensions.is((SELECT detail FROM public.commit_paper_signup_batch('b1600000-0000-4000-8000-000000000001','b1100000-0000-4000-8000-000000000001',ARRAY['b1700000-0000-4000-8000-000000000001']::uuid[],false,'b1500000-0000-4000-8000-000000000003')),'published_attendance_requires_correction','paper review cannot replace legacy award intervals with different breaks but equal endpoints and minutes');
SELECT extensions.is((SELECT attendance_revision FROM public.project_signups WHERE id='b1300000-0000-4000-8000-000000000001'),2,'refused paper replacement preserves the awarded revision');
SELECT extensions.is(public.request_corrected_certificate_delivery('b1200000-0000-4000-8000-000000000001','b1400000-0000-4000-8000-000000000001',2,'b1500000-0000-4000-8000-000000000004','b1100000-0000-4000-8000-000000000001')->'deliveries'->0->>'creditedMinutes','120','explicit resend supports a corrected NULL-type certificate');
UPDATE public.projects SET published='{}' WHERE id='b1200000-0000-4000-8000-000000000001';
SELECT extensions.is(public.publish_volunteer_hours_transactional('b1100000-0000-4000-8000-000000000001','b1200000-0000-4000-8000-000000000001','oneTime','[{"signupId":"b1300000-0000-4000-8000-000000000003","checkIn":"2020-09-18T09:00:00Z","checkOut":"2020-09-18T10:00:00Z","attendanceRevision":0}]','hours-publication:v1:'||repeat('b2',32))->>'outcome','accepted','existing legacy awards satisfy completeness when publishing another volunteer');
SELECT extensions.is((SELECT count(*)::integer FROM public.certificates WHERE project_id='b1200000-0000-4000-8000-000000000001'),3,'mixed legacy and current publication keeps one award per volunteer');
INSERT INTO public.projects(id,creator_id,title,location,description,event_type,verification_method,schedule,status,project_timezone,published)
SELECT 'b1200000-0000-4000-8000-000000000002',creator_id,'Unlinked historical award','Local','Synthetic orphan award',event_type,verification_method,schedule,status,project_timezone,'{"oneTime":true}' FROM public.projects WHERE id='b1200000-0000-4000-8000-000000000001';
INSERT INTO public.project_signups(id,project_id,user_id,schedule_id,status) VALUES('b1300000-0000-4000-8000-000000000004','b1200000-0000-4000-8000-000000000002','b1100000-0000-4000-8000-000000000002','oneTime','approved');
INSERT INTO public.certificates(id,project_id,user_id,project_title,event_start,event_end,is_certified,type,check_in_method,schedule_id)
VALUES('b1400000-0000-4000-8000-000000000004','b1200000-0000-4000-8000-000000000002','b1100000-0000-4000-8000-000000000002','Unlinked historical title','2020-09-18T09:00:00Z','2020-09-18T13:00:00Z',false,NULL,'manual','0');
CREATE TEMP TABLE orphan_snapshot AS SELECT to_jsonb(certificates) AS value FROM public.certificates WHERE id='b1400000-0000-4000-8000-000000000004';
SELECT extensions.throws_ok($$SELECT public.record_project_attendance('b1300000-0000-4000-8000-000000000004',0,'Unlinked award transcription','[{"checkIn":"2020-09-18T09:00:00Z","checkOut":"2020-09-18T13:00:00Z"}]','b1500000-0000-4000-8000-000000000005','b1100000-0000-4000-8000-000000000001')$$,'23505','unlinked platform award requires reconciliation','recording fails closed for the same account and session orphan award');
SELECT extensions.throws_ok($$UPDATE public.project_signups SET status='attended',check_in_time='2020-09-18T09:00:00Z',check_out_time='2020-09-18T13:00:00Z' WHERE id='b1300000-0000-4000-8000-000000000004'$$,'23505','unlinked platform award requires reconciliation','late attendance cannot silently duplicate an unlinked historical award');
SELECT extensions.is((SELECT to_jsonb(certificates) FROM public.certificates WHERE id='b1400000-0000-4000-8000-000000000004'),(SELECT value FROM orphan_snapshot),'refused reconciliation preserves the orphan award snapshot and URL');
SELECT extensions.is((SELECT count(*)::integer FROM public.certificates WHERE project_id='b1200000-0000-4000-8000-000000000002'),1,'unlinked historical account award remains the only credit');
UPDATE public.certificates SET schedule_id=NULL WHERE id='b1400000-0000-4000-8000-000000000004';
SELECT extensions.throws_ok($$SELECT public.record_project_attendance('b1300000-0000-4000-8000-000000000004',0,'Missing historical session','[{"checkIn":"2020-09-18T09:00:00Z","checkOut":"2020-09-18T13:00:00Z"}]','b1500000-0000-4000-8000-000000000006','b1100000-0000-4000-8000-000000000001')$$,'23505','unlinked platform award requires reconciliation','one-time orphan award without a session reference cannot be duplicated');
INSERT INTO public.projects(id,creator_id,title,location,description,event_type,verification_method,schedule,status,project_timezone)
VALUES('b1200000-0000-4000-8000-000000000003','b1100000-0000-4000-8000-000000000001','Ambiguous historical award','Local','Synthetic missing session','multiDay','manual','{"multiDay":[{"date":"2020-09-18","slots":[{"startTime":"09:00","endTime":"15:00","volunteers":5}]},{"date":"2020-09-19","slots":[{"startTime":"09:00","endTime":"15:00","volunteers":5}]}]}','upcoming','UTC');
INSERT INTO public.project_signups(id,project_id,user_id,schedule_id,status) VALUES('b1300000-0000-4000-8000-000000000005','b1200000-0000-4000-8000-000000000003','b1100000-0000-4000-8000-000000000002','2020-09-18-0','approved');
INSERT INTO public.certificates(id,project_id,user_id,project_title,event_start,event_end,is_certified,type,check_in_method,schedule_id)
VALUES('b1400000-0000-4000-8000-000000000005','b1200000-0000-4000-8000-000000000003','b1100000-0000-4000-8000-000000000002','Missing historical session','2020-09-18T09:00:00Z','2020-09-18T13:00:00Z',false,NULL,'manual',NULL);
SELECT extensions.throws_ok($$SELECT public.record_project_attendance('b1300000-0000-4000-8000-000000000005',0,'Ambiguous historical session','[{"checkIn":"2020-09-18T09:00:00Z","checkOut":"2020-09-18T13:00:00Z"}]','b1500000-0000-4000-8000-000000000007','b1100000-0000-4000-8000-000000000001')$$,'23505','unlinked platform award requires reconciliation','an ambiguous orphan session fails closed without guessing its association');
UPDATE public.certificates SET schedule_id='2020-09-19-0' WHERE id='b1400000-0000-4000-8000-000000000005';
SELECT extensions.lives_ok($$SELECT public.record_project_attendance('b1300000-0000-4000-8000-000000000005',0,'Different historical session','[{"checkIn":"2020-09-18T09:00:00Z","checkOut":"2020-09-18T13:00:00Z"}]','b1500000-0000-4000-8000-000000000008','b1100000-0000-4000-8000-000000000001')$$,'a known different session does not block completed attendance recording');
SELECT * FROM extensions.finish();
ROLLBACK;
